# Generated by cmd/release in airiclenz/photon and overwritten at each release: edit
# cmd/release/templates/photon.rb.tmpl there, never this file.
class Photon < Formula
  desc "Record, check and render a terminal app's demo clip from its storyboard"
  homepage "https://github.com/airiclenz/photon"
  version "0.0.0"
  license "MIT"

  # Installs the prebuilt binary for this platform rather than compiling, so no Go
  # toolchain is needed. The tree is CGO-free, so all six release targets come off
  # one `cmd/release dist` in the project repo.
  on_macos do
    on_arm do
      url "https://github.com/airiclenz/photon/releases/download/v0.0.0/photon_0.0.0_darwin_arm64.tar.gz"
      sha256 "1111111111111111111111111111111111111111111111111111111111111111"
    end
    on_intel do
      url "https://github.com/airiclenz/photon/releases/download/v0.0.0/photon_0.0.0_darwin_amd64.tar.gz"
      sha256 "2222222222222222222222222222222222222222222222222222222222222222"
    end
  end

  on_linux do
    on_arm do
      url "https://github.com/airiclenz/photon/releases/download/v0.0.0/photon_0.0.0_linux_arm64.tar.gz"
      sha256 "3333333333333333333333333333333333333333333333333333333333333333"
    end
    on_intel do
      url "https://github.com/airiclenz/photon/releases/download/v0.0.0/photon_0.0.0_linux_amd64.tar.gz"
      sha256 "4444444444444444444444444444444444444444444444444444444444444444"
    end
  end

  def install
    bin.install "photon"
  end

  test do
    # `photon version` prints the bare version, X.Y.Z.
    assert_match version.to_s, shell_output("#{bin}/photon version")
  end
end
